import math

state = {'t0': None, 'saw_left': False, 'printed_init': False, 'snapshots': []}

def to_veh_xy(origin, pts):
    ox, oy = origin
    out = []
    for b_deg, d_m in pts:
        b = math.radians(b_deg)
        out.append((round(ox + d_m * math.cos(b), 2), round(oy + d_m * math.sin(b), 2), round(b_deg, 1), round(d_m, 2)))
    return out

def control(obs):
    if state['t0'] is None:
        state['t0'] = obs['t']
    if not state['printed_init']:
        print('RIG:', obs['rig'])
        print('SPEED:', obs['speed'])
        state['printed_init'] = True

    views = obs.get('views', {})
    if not state['saw_left']:
        look = 53.0
        if 'left_mirror' in views and views['left_mirror'].get('walls'):
            state['saw_left'] = True
            lm = views['left_mirror']
            dv = views.get('direct', {})
            print('LEFT_MIRROR walls (veh xy):', to_veh_xy(lm['origin'], lm['walls']))
            if dv.get('walls'):
                print('LEFT_DIRECT walls (veh xy):', to_veh_xy(dv['origin'], dv['walls']))
            look = -41.0
    else:
        look = -41.0
        if 'camera' in views and len(state['snapshots']) < 2:
            cam = views['camera']
            dv = views.get('direct', {})
            state['snapshots'].append(obs['t'])
            print(f"CAM t={obs['t']:.1f} walls (veh xy):", to_veh_xy(cam['origin'], cam.get('walls', [])))
            if cam.get('target_corners'):
                print('CAM target_corners:', to_veh_xy(cam['origin'], cam['target_corners']))
            if dv.get('walls'):
                print(f"RIGHT_DIRECT t={obs['t']:.1f} walls (veh xy):", to_veh_xy(dv['origin'], dv['walls']))

    # Keep trailer straight while starting reverse
    hitch = obs['hitch_deg']
    steer = max(-15.0, min(15.0, 2.0 * hitch))
    return steer, -1.3, look

